import{_ as o,o as d,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"サンプルプラグイン","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/examples.md","filePath":"ja-JP/dev-guide/examples.md","lastUpdated":1785993908000}'),c={name:"ja-JP/dev-guide/examples.md"};function a(t,e,n,s,l,P){return d(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="サンプルプラグイン" tabindex="-1">サンプルプラグイン <a class="header-anchor" href="#サンプルプラグイン" aria-label="Permalink to &quot;サンプルプラグイン&quot;">​</a></h1><p>Lertaro 自身には2つのプラグインが同梱されており、実際の参考例として非常に役立ちます——どちらも Lertaro リポジトリの <code>Plugins/</code> フォルダーにあります。</p><h2 id="coreextensions-—-アクションとシェルのコンテキストメニュー" tabindex="-1">CoreExtensions — アクションとシェルのコンテキストメニュー <a class="header-anchor" href="#coreextensions-—-アクションとシェルのコンテキストメニュー" aria-label="Permalink to &quot;CoreExtensions — アクションとシェルのコンテキストメニュー&quot;">​</a></h2><p><code>CoreExtensionsPlugin</code> は <code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code> の3つのインターフェースを同時に実装しています。</p><ul><li><strong><code>IActionProvider.GetActions()</code></strong> は10個の組み込み <code>ISearchResultAction</code> を返します——開く、 Explorer で開く場所を表示、パスのコピー、ファイル自体のコピー/切り取り、その場所でコマンドプロンプトを開く、touch/mkdir、そして開くとコマンドプロンプトの昇格(管理者として実行)バリアントです。</li><li><strong><code>IActionProvider.GetDynamicActionProviders()</code></strong> は単一の <code>IDynamicActionProvider</code> である <code>ShellMenuActionProvider</code> を返します。これが、実際の Windows 右クリックメニュー(「送る」のようなネストされたカスケードサブメニューを含む)を Lertaro 自身のアクションメニューの中に表示させている仕組みです。固定のアクションリストではなく、<em>任意の</em>外部の、動的に構築されるメニューを Lertaro 内に表示したい場合に真似すべきパターンです。</li><li><strong><code>IConfigurable.GetConfigSchema()</code></strong> は、ネストされたフィールドグループと <code>StringList</code> フィールドタイプを使った設定スキーマの例を示しています——自分のプラグインの 設定 → プラグイン の設定ダイアログに、フラットなブール値のリスト以上のものが必要な場合は一読の価値があります。</li><li>5つのプロバイダーが <a href="./sdk/ui-extensions.html#iquickpaneltabprovider"><code>IQuickPanelTabProvider</code></a> を実装しており、これらでインターフェースの両極をカバーしています。<code>FavoritesTabProvider</code> と <code>HistoryTabProvider</code> はメモリ上のリストをそのまま返すだけ — どちらも独自の状態を持たないため、最小限のリファレンス実装です。<code>WindowsRecentTabProvider</code> はもう一方の極で、バックグラウンドタスクでディレクトリを読み、COM 経由でシェルのショートカットを解決し、高価な処理の<strong>前に</strong>件数を打ち切り、各項目の <code>Metadata.Modified</code> を埋めてタブの新しい順に意味を持たせています。</li><li><code>LastDirectoryTabProvider</code> と <code>RecentFilesTabProvider</code> を読む理由は少し違います:どちらも自前のデータをまったく持たず、 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> と <code>RecentFilesService</code> を通じてホストに尋ねています。プラグインで見せたいものを Lertaro がすでに知っている場合は、このパターンをまねてください。</li></ul><h2 id="pinyinalias-—-中国語ファイル名向けのピンインエイリアス" tabindex="-1">PinyinAlias — 中国語ファイル名向けのピンインエイリアス <a class="header-anchor" href="#pinyinalias-—-中国語ファイル名向けのピンインエイリアス" aria-label="Permalink to &quot;PinyinAlias — 中国語ファイル名向けのピンインエイリアス&quot;">​</a></h2><p><code>PinyinAliasProvider</code> は <code>IAliasProvider</code> と <code>ITranslationProvider</code> の両方を実装しています——プラグインは関連する SDK の役割を自由に組み合わせることができ、これはその良いテンプレートです。</p><ul><li><strong><code>IAliasProvider.InputRanges</code>/<code>OutputRanges</code></strong> は、<code>PinyinEngine</code> 自身のテーブルの境界値から2つのアルファベットをそのまま宣言しています(<code>InputRanges</code>:CJK ブロック、<code>OutputRanges</code>:<code>a</code>-<code>z</code>)。マジックナンバーを重複させないためです——ホストはこれら両方を使って、<code>大长今</code> に対する <code>大cj</code> のような、文字リテラルとピンインを混在させたクエリをサポートします。</li><li><strong><code>IAliasProvider.CanHandle(text)</code></strong> は、実際の処理を行う前にまず中国語文字が含まれているかをスキャンするため、中国語以外のファイル名はエイリアス生成を完全にスキップします。</li><li><strong><code>IAliasProvider.GetAliases(text)</code></strong> は文字単位の音節テーブル(各漢字が取りうるピンイン読みへのマッピング)を構築し、フルピンインのエイリアスと頭文字のみのエイリアスの両方を生成します。多音字 (有効な読みが複数ある文字)を含むファイル名については、一般的な組み合わせすべてに対してエイリアスを生成します——病的な入力での組み合わせ爆発を避けるため上限は32通りです——各候補は <code>|</code> で連結され、検索エンジンはそれらすべてが同時に一致することを要求するのではなく、それぞれを個別の候補として扱います。</li><li><strong><code>ITranslationProvider</code></strong> は<em>同じ</em>クラスに実装されていますが、これは純粋にこのプラグイン自身の UI 文字列(表示名など)を <code>TranslationService.LoadEmbeddedTranslations</code> 経由で提供するためのものです——両インターフェースは目的としては無関係ですが、この小さな単一ファイルのプラグインではたまたま 1つの型にまとまっています。</li><li><code>lock</code> で保護された <code>Dictionary&lt;string, Dictionary&lt;string, string&gt;&gt;</code> のキャッシュにより、呼び出しのたびに埋め込みの翻訳 JSON を再パースすることを避けています——<code>GetTranslations</code> の中で軽くない処理を行うプラグインにとっての標準的なパターンです。</li></ul><p>両方のプラグインを並べて読むことが、<a href="./sdk/core-search-actions.html">プラグイン SDK リファレンス</a>の各パーツが実際にどう組み合わさるかを理解する最も手っ取り早い方法です。</p>',9)])])}const p=o(c,[["render",a]]);export{u as __pageData,p as default};
